import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../../core/constants/app_constants.dart';
import '../../core/utils/currency_utils.dart';
import '../../data/models/expense.dart';
class CategoryDonutChart extends StatefulWidget{const CategoryDonutChart({super.key,required this.data});final List<CategoryTotal> data;@override State<CategoryDonutChart> createState()=>_CategoryDonutChartState();}
class _CategoryDonutChartState extends State<CategoryDonutChart> with SingleTickerProviderStateMixin{late AnimationController c;@override void initState(){super.initState();c=AnimationController(vsync:this,duration:const Duration(milliseconds:800))..forward();}@override void didUpdateWidget(covariant CategoryDonutChart old){super.didUpdateWidget(old);if(old.data!=widget.data)c..reset()..forward();}@override void dispose(){c.dispose();super.dispose();}Color color(String x,ColorScheme s){final i=ExpenseCategory.values.indexWhere((e)=>e.label==x);return [s.primary,s.secondary,s.tertiary,s.error,Colors.teal][i<0?0:i%5];}@override Widget build(BuildContext context){if(widget.data.isEmpty)return const SizedBox(height:220,child:Center(child:Text('No spending data yet.')));final total=widget.data.fold(0,(s,e)=>s+e.amount);return Column(children:[SizedBox(height:220,child:AnimatedBuilder(animation:c,builder:(context,_)=>CustomPaint(painter:_Painter(widget.data,total,c.value,(x)=>color(x,Theme.of(context).colorScheme)),child:Center(child:Text(formatVnd(total),style:const TextStyle(fontWeight:FontWeight.w900)))))),...widget.data.take(5).map((e)=>ListTile(dense:true,leading:CircleAvatar(radius:5,backgroundColor:color(e.category,Theme.of(context).colorScheme)),title:Text(e.category),trailing:Text(formatVnd(e.amount))))]);}}
class _Painter extends CustomPainter{_Painter(this.data,this.total,this.progress,this.colorFor);final List<CategoryTotal> data;final int total;final double progress;final Color Function(String) colorFor;@override void paint(Canvas canvas,Size size){final center=size.center(Offset.zero),r=math.min(size.width,size.height)*.32;var start=-math.pi/2;for(final e in data){final sweep=e.amount/total*math.pi*2;canvas.drawArc(Rect.fromCircle(center:center,radius:r),start,sweep*progress,false,Paint()..style=PaintingStyle.stroke..strokeWidth=32..color=colorFor(e.category));start+=sweep;}}@override bool shouldRepaint(covariant _Painter old)=>old.progress!=progress||old.data!=data;}
